{-# LANGUAGE OverloadedStrings #-}\nimport Fluxus.Compiler.Driver\nimport Fluxus.CodeGen.CPP\nimport Fluxus.AST.Common\nimport Fluxus.AST.Python\nimport qualified Data.Text as T\nimport qualified Data.Text.IO as TIO\n\n-- Create a simple Python AST for testing\ntestAST :: PythonAST\ntestAST = PythonAST $ PythonModule\n  { pyModuleName = Nothing\n  , pyModuleDoc = Nothing\n  , pyModuleImports = []\n  , pyModuleBody = \n      [ Located (SourceSpan \"test.py\" (SourcePos 0 0) (SourcePos 0 0)) $\n          PyFuncDef $ PythonFuncDef\n            { pyFuncName = Identifier \"add\"\n            , pyFuncDecorators = []\n            , pyFuncParams = \n                [ Located (SourceSpan \"test.py\" (SourcePos 0 0) (SourcePos 0 0)) $\n                    ParamNormal (Identifier \"x\") Nothing Nothing\n                , Located (SourceSpan \"test.py\" (SourcePos 0 0) (SourcePos 0 0)) $\n                    ParamNormal (Identifier \"y\") Nothing Nothing\n                ]\n            , pyFuncReturns = Nothing\n            , pyFuncBody = \n                [ Located (SourceSpan \"test.py\" (SourcePos 0 0) (SourcePos 0 0)) $\n                    PyReturn $ Just $ \n                      Located (SourceSpan \"test.py\" (SourcePos 0 0) (SourcePos 0 0)) $\n                        PyBinaryOp OpAdd\n                          (Located (SourceSpan \"test.py\" (SourcePos 0 0) (SourcePos 0 0)) $ PyVar $ Identifier \"x\")\n                          (Located (SourceSpan \"test.py\" (SourcePos 0 0) (SourcePos 0 0)) $ PyVar $ Identifier \"y\")\n                ]\n            , pyFuncDoc = Nothing\n            , pyFuncIsAsync = False\n            }\n      , Located (SourceSpan \"test.py\" (SourcePos 0 0) (SourcePos 0 0)) $\n          PyAssign \n            [ Located (SourceSpan \"test.py\" (SourcePos 0 0) (SourcePos 0 0)) $ \n                PatVar $ Identifier \"result\"\n            ]\n            (Located (SourceSpan \"test.py\" (SourcePos 0 0) (SourcePos 0 0)) $\n              PyCall \n                (Located (SourceSpan \"test.py\" (SourcePos 0 0) (SourcePos 0 0)) $ \n                  PyVar $ Identifier \"add\")\n                [ Located (SourceSpan \"test.py\" (SourcePos 0 0) (SourcePos 0 0)) $ \n                    ArgPositional $ \n                      Located (SourceSpan \"test.py\" (SourcePos 0 0) (SourcePos 0 0)) $ \n                        PyLiteral $ PyInt 1\n                , Located (SourceSpan \"test.py\" (SourcePos 0 0) (SourcePos 0 0)) $ \n                    ArgPositional $ \n                      Located (SourceSpan \"test.py\" (SourcePos 0 0) (SourcePos 0 0)) $ \n                        PyLiteral $ PyInt 2\n                ]\n            )\n      ]\n  }\n\nmain :: IO ()\nmain = do\n  putStrLn \"Testing C++ code generation with debug output...\"\n  let config = CppGenConfig\n        { cgcOptimizationLevel = 2\n        , cgcEnableInterop = True\n        , cgcTargetCppStd = \"c++20\"\n        , cgcUseSmartPointers = True\n        , cgcEnableParallel = True\n        , cgcEnableCoroutines = True\n        , cgcNamespace = \"hyperstatic\"\n        , cgcHeaderGuard = \"HYPERSTATIC_GENERATED\"\n        }\n  let cppUnit = generateCppMain config (Left testAST)\n  putStrLn \"Generated C++ unit:\"\n  putStrLn $ showCppUnit cppUnit\n\nshowCppUnit :: CppUnit -> String\nshowCppUnit (CppUnit includes _ decls) = \n  let renderedCode = unlines $\n        [ \"// Generated by HyperStatic/CXX Compiler - DEBUG VERSION\" ] ++\n        map (\\inc -> \"#include \" ++ show inc) includes ++\n        [ \"\" ] ++\n        map showCppDecl decls\n  in renderedCode\n\nshowCppDecl :: CppDecl -> String\nshowCppDecl = \\case\n  CppFunction name retType params body -> \n    (showCppType retType) ++ \" \" ++ (show name) ++ \"(\" ++ \n    (intercalate \", \" (map showCppParam params)) ++ \") {\\n\" ++\n    (unlines (map (\"    \" ++) (map showCppStmt body))) ++\n    \"}\\n\"\n  CppVariable name varType Nothing -> \n    case varType of\n      CppArray elemType size -> \n        (showCppType elemType) ++ \" \" ++ (show name) ++ \"[\" ++ (show size) ++ \"];\\n\"\n      _ -> \n        (showCppType varType) ++ \" \" ++ (show name) ++ \";\\n\"\n  CppVariable name varType (Just expr) -> \n    case varType of\n      CppArray elemType size -> \n        (showCppType elemType) ++ \" \" ++ (show name) ++ \"[\" ++ (show size) ++ \"] = \" ++ (showCppExpr expr) ++ \";\\n\"\n      _ -> \n        (showCppType varType) ++ \" \" ++ (show name) ++ \" = \" ++ (showCppExpr expr) ++ \";\\n\"\n  CppCommentDecl comment ->\n    \"// \" ++ (show comment)\n  _ -> \"// TODO: Render other declaration types\\n\"\n\nshowCppStmt :: CppStmt -> String\nshowCppStmt = \\case\n  CppReturn Nothing -> \"return;\"\n  CppReturn (Just expr) -> \"return \" ++ (showCppExpr expr) ++ \";\"\n  CppExprStmt expr -> (showCppExpr expr) ++ \";\"\n  CppComment comment -> \"// \" ++ (show comment)\n  _ -> \"// TODO: Render other statement types\"\n\nshowCppExpr :: CppExpr -> String\nshowCppExpr = \\case\n  CppVar name -> show name\n  CppLiteral lit -> showCppLiteral lit\n  CppBinary op left right -> \n    (showCppExpr left) ++ \" \" ++ (show op) ++ \" \" ++ (showCppExpr right)\n  CppCall func args ->\n    (showCppExpr func) ++ \"(\" ++ (intercalate \", \" (map showCppExpr args)) ++ \")\"\n  _ -> \"/* unimplemented expr */\"\n\nshowCppType :: CppType -> String\nshowCppType = \\case\n  CppVoid -> \"void\"\n  CppInt -> \"int\" \n  CppDouble -> \"double\"\n  CppBool -> \"bool\"\n  CppString -> \"std::string\"\n  CppAuto -> \"auto\"\n  CppVector elemType -> \"std::vector<\" ++ (showCppType elemType) ++ \">\"\n  CppTuple types -> \"std::tuple<\" ++ (intercalate \", \" (map showCppType types)) ++ \">\"\n  _ -> \"auto\"\n\nshowCppParam :: CppParam -> String\nshowCppParam (CppParam name paramType mdefault) = \n  let base = (showCppType paramType) ++ \" \" ++ (show name)\n  in case mdefault of\n       Nothing -> base\n       Just defaultValue -> base ++ \" = \" ++ (showCppExpr defaultValue)\n\nshowCppLiteral :: CppLiteral -> String\nshowCppLiteral = \\case\n  CppIntLit i -> show i\n  CppFloatLit f -> show f\n  CppBoolLit True -> \"true\"\n  CppBoolLit False -> \"false\" \n  CppStringLit s -> \"\\\"\" ++ (show s) ++ \"\\\"\"\n  _ -> \"/* unimplemented literal */\"\n  \nintercalate :: String -> [String] -> String\nintercalate sep xs = concat (intersperse sep xs)\n\nintersperse :: a -> [a] -> [a]\nintersperse _ [] = []\nintersperse _ [x] = [x]\nintersperse sep (x:xs) = x : sep : intersperse sep xs